Draft.autoImportGroupId" :items="store.catalog.groups" item-title="name" item-value="id" label="Auto-assign deployment group" class="full"/><v-alert type="info" variant="tonal" density="compact" class="full">{{ proxmoxDraft.kind === 'node' ? 'Queries the selected node QEMU or LXC endpoint.' : 'Queries the cluster resources endpoint and can include QEMU guests, LXC containers, or both.' }} API tokens are encrypted before storage and never returned to the browser.</v-alert><div class="actions full"><v-btn variant="text" @click="proxmoxConnectorWindow = false">Cancel</v-btn><v-btn class="glass-button" type="submit">Save Proxmox Connector</v-btn></div></form></FloatingWindow>
